class Statement{
 constructor(sql,params=[]){this.sql=sql;this.params=params}
 bind(...params){return new Statement(this.sql,params)}
 prepare(){assert.ok(this.params.length<=100,'Hosted bind budget exceeded');beforeExecute?.(this.sql,this.params);return sqlite.prepare(this.sql)}
 async raw(){const statement=this.prepare();statement.setReturnArrays(true);return statement.all(...this.params)}
 allSync(){return {results:this.prepare().all(...this.params),success:true,meta:{}}}
 async all(){return this.allSync()}
 async run(){const result=this.prepare().run(...this.params);return {results:[],success:true,meta:{changes:result.changes,last_row_id:Number(result.lastInsertRowid)}}}
}
