async function fakeFetch(url,options={}){
 const parsed=new URL(url);assert.equal(parsed.origin,'https://api.stripe.com','Real network is forbidden');
 const route=parsed.pathname,method=options.method||'GET',fields=Object.fromEntries(new URLSearchParams(options.body||'')),headers=new Headers(options.headers);
 const request={route,method,fields,key:headers.get('Idempotency-Key'),at:clock.now};processor.requests.push(request);
 assert.equal(headers.get('Authorization'),'Bearer '+testConfig.COMMERCE_STRIPE_TEST_SECRET_KEY);
 assert.equal(options.redirect,'error');
 const replacement=await processor.override?.(request);if(replacement!==undefined)return replacement;
 const cacheKey=method+':'+route+':'+request.key;
 if(method==='POST'&&processor.keys.has(cacheKey)){
  const saved=processor.keys.get(cacheKey);if(JSON.stringify(saved.fields)!==JSON.stringify(fields))return json({error:{message:'SYNTHETIC IDEMPOTENCY CONFLICT'}},409);return json(saved.object);
 }
 let value;
 if(method==='POST'&&route==='/v1/accounts'){
  const id='acct_'+suffix(request.key);value={id,object:'account',livemode:false,country:'US',metadata:{profile_id:fields['metadata[profile_id]'],user_id:fields['metadata[user_id]']},details_submitted:true,payouts_enabled:true,capabilities:{transfers:'active'}};processor.accounts.set(id,value);
 }else if(method==='POST'&&route==='/v1/account_links')value={object:'account_link',livemode:false,expires_at:Math.floor(clock.now/1000)+300,url:'https://connect.stripe.com/setup/SYNTHETIC'+suffix(request.key)};
 else if(method==='GET'&&route.startsWith('/v1/accounts/'))value=processor.accounts.get(route.split('/').at(-1));
 else if(method==='POST'&&route==='/v1/checkout/sessions'){
  const id='cs_test_'+suffix(request.key),amount=Object.entries(fields).filter(([key])=>/^line_items\[\d+\]\[price_data\]\[unit_amount\]$/.test(key)).reduce((sum,[,amount])=>sum+Number(amount),0);
  value={id,object:'checkout.session',livemode:false,mode:'payment',currency:'usd',amount_total:amount,client_reference_id:fields.client_reference_id,metadata:meta(fields),status:'open',payment_status:'unpaid',payment_intent:null,url:'https://checkout.stripe.com/c/pay/'+id};processor.sessions.set(id,value);
 }else if(method==='GET'&&route.startsWith('/v1/checkout/sessions/'))value=processor.sessions.get(route.split('/').at(-1));
 else if(method==='GET'&&route.startsWith('/v1/payment_intents/'))value=processor.intents.get(route.split('/').at(-1));
 else if(method==='GET'&&route.startsWith('/v1/charges/'))value=processor.charges.get(route.split('/').at(-1));
 else if(method==='GET'&&route.startsWith('/v1/refunds/'))value=processor.refunds.get(route.split('/').at(-1));
 else if(method==='POST'&&route==='/v1/refunds'){
  const id='re_'+suffix(request.key);value={id,object:'refund',livemode:false,payment_intent:fields.payment_intent,amount:Number(fields.amount),currency:'usd',metadata:meta(fields),status:'succeeded'};processor.refunds.set(id,value);
 }else if(route==='/v1/transfers')throw Error('No API transfer is permitted without trusted carrier proof');
 if(!value)return json({error:{message:'SYNTHETIC UNKNOWN OBJECT'}},404);
 if(method==='POST')processor.keys.set(cacheKey,{fields,object:value});return json(value);
}
